SELECT clschange.class_id, clschange.id, clschange.class_time_id, clschange.cls_start_time, clschange.cls_end_time, clschange.original_start_time, clschange.original_end_time, clschange.type, cls.class_name className, course.course_name courseName, bis.`name` bishop_teacher_name, help.`name` help_teacher_name , cls.sum_students sum_students , cls.exist_students exist_students , course.color course_color FROM bd_class_change clschange LEFT JOIN bd_class cls ON clschange.class_id = cls.id LEFT JOIN bd_course course ON course.id = cls.class_course_id LEFT JOIN bd_teacher bis ON cls.bishop_teacher_id = bis.id LEFT JOIN bd_teacher help ON cls.help_teacher_id = help.id
clschange.type in (1,2) and clschange.is_delete = 0
and clschange.mec_id = #{mecId}
and clschange.campus_id = #{campusId}
and cls.id = #{classId}
and ((clschange.cls_end_time > #{startDate} and clschange.cls_end_time < #{endDate}) OR (clschange.cls_start_time > #{startDate} and clschange.cls_start_time < #{endDate}) OR (clschange.cls_start_time > #{startDate} and clschange.cls_end_time < #{endDate}) OR (clschange.cls_start_time < #{startDate} and clschange.cls_end_time > #{endDate}) )
and cls.class_name like CONCAT('%',#{className},'%')
and course.course_name like CONCAT('%',#{courseName},'%')

SELECT clschange.class_id, clschange.id, clschange.class_time_id, clschange.cls_start_time, clschange.cls_end_time, clschange.original_start_time, clschange.original_end_time, clschange.type, cls.class_name className, course.course_name courseName , bis.`name` bishop_teacher_name, help.`name` help_teacher_name , cls.sum_students sum_students , cls.exist_students exist_students , course.color course_color FROM bd_class_change clschange LEFT JOIN bd_class cls ON clschange.class_id = cls.id LEFT JOIN bd_course course ON course.id = cls.class_course_id LEFT JOIN bd_teacher bis ON cls.bishop_teacher_id = bis.id LEFT JOIN bd_teacher help ON cls.help_teacher_id = help.id
clschange.type in (0,2) and clschange.is_delete = 0
and clschange.mec_id = #{mecId}
and clschange.campus_id = #{campusId}
and cls.id = #{classId}
and ((clschange.original_end_time > #{startDate} and clschange.original_end_time < #{endDate}) OR (clschange.original_start_time > #{startDate} and clschange.original_start_time < #{endDate}) OR (clschange.original_start_time > #{startDate} and clschange.original_end_time < #{endDate}) OR (clschange.original_start_time < #{startDate} and clschange.original_end_time > #{endDate}) )
and cls.class_name like CONCAT('%',#{className},'%')
and course.course_name like CONCAT('%',#{courseName},'%')

SELECT *
FROM bd_class_change
WHERE class_time_id = #{classTimeId}
  AND is_delete = 0
  and cls_start_time >= now();

